{
  "template": "trigger"
}

namespace pk;
table Settings {
  doses_mg:[double];
  intervals_h:[double];
  half_life_h:double;
  ka_per_h:double;
  volume_l:double;
  bioavailability:double;
  low_mg_l:double;
  high_mg_l:double;
  days:double;
}
table Outputs { settings:Settings (required); }
root_type Outputs;

{
  "template": "input",
  "params": [
    {
      "name": "doses_mg",
      "type": "double[]",
      "data": [
        400.0,
        200.0,
        100.0,
        200.0
      ]
    },
    {
      "name": "intervals_h",
      "type": "double[]",
      "data": [
        24.0,
        12.0,
        6.0,
        24.0
      ]
    },
    {
      "name": "half_life_h",
      "type": "double",
      "data": 8.0
    },
    {
      "name": "ka_per_h",
      "type": "double",
      "data": 1.0
    },
    {
      "name": "volume_l",
      "type": "double",
      "data": 40.0
    },
    {
      "name": "bioavailability",
      "type": "double",
      "data": 0.8
    },
    {
      "name": "low_mg_l",
      "type": "double",
      "data": 2.0
    },
    {
      "name": "high_mg_l",
      "type": "double",
      "data": 6.0
    },
    {
      "name": "days",
      "type": "double",
      "data": 5.0
    }
  ]
}

namespace pk;
table Curves {
  doses_mg:[double];
  intervals_h:[double];
  half_life_h:double;
  ka_per_h:double;
  volume_l:double;
  bioavailability:double;
  low_mg_l:double;
  high_mg_l:double;
  days:double;
  t_h:[double];
  conc:[double];
  first_trough:[double];
  last_trough:[double];
  last_dose_h:[double];
}
table Outputs { curves:Curves (required); }
root_type Outputs;

{ pkgs, inputs, params }:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
    inherit sdk;
    src = ./src;
    packages = ps: [ ps.numpy ps.scipy ps.plotly ];
  };
}

{
  "language": "python",
  "inputs": [
    {
      "name": "settings"
    }
  ]
}

{
  "template": "fork",
  "params": [
    {
      "name": "branches",
      "type": "string[]",
      "data": [
        "check",
        "window",
        "missed"
      ]
    }
  ]
}

